import pyomo.environ as pyo

DATA = {
    "nodes": ["S", "2", "3", "4", "5", "6", "7", "T"],
    "arcs": [
        ("S", "2", 4), ("S", "3", 5),
        ("2", "S", 5), ("2", "4", 3), ("2", "3", 2),
        ("3", "S", 4), ("3", "2", 2), ("3", "5", 1), ("3", "6", 7),
        ("4", "2", 3), ("4", "6", 2),
        ("5", "3", 1), ("5", "T", 5),
        ("6", "3", 7), ("6", "4", 2), ("6", "7", 3),
        ("7", "6", 3), ("7", "T", 1),
        ("T", "5", 5), ("T", "7", 1),
    ],
    "source": "S",
    "sink": "T",
    "supply": 1.0,
    "arc_capacity": 1.0,
}


def build_model(data=None):
    d = data or DATA

    arcs = d["arcs"]
    arc_keys = [(u, v, k) for k, (u, v, _) in enumerate(arcs)]
    cost = {(u, v, k): w for k, (u, v, w) in enumerate(arcs)}
    tail = {a: a[0] for a in arc_keys}
    head = {a: a[1] for a in arc_keys}

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=d["nodes"])
    model.A = pyo.Set(initialize=arc_keys, dimen=3)

    model.flow = pyo.Var(
        model.A,
        within=pyo.NonNegativeReals,
        bounds=(0.0, d["arc_capacity"]),
    )

    def obj_rule(m):
        return sum(cost[a] * m.flow[a] for a in m.A)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def supply_of(n):
        if n == d["source"]:
            return d["supply"]
        if n == d["sink"]:
            return -d["supply"]
        return 0.0

    def conservation_rule(m, n):
        out_flow = sum(m.flow[a] for a in m.A if tail[a] == n)
        in_flow = sum(m.flow[a] for a in m.A if head[a] == n)
        return out_flow - in_flow == supply_of(n)

    model.conservation = pyo.Constraint(model.N, rule=conservation_rule)

    return model


